import math

def is_not_prime(n):
    if n <= 1:
        return True
    i = 2
    while i <= math.sqrt(n):
        if n % i == 0:
            return True
        i += 1
    return False

def main():
    assert not is_not_prime(2)
    assert not is_not_prime(2)
    assert is_not_prime(2) == False

main()

