def max_sum(arr):
    if not arr:
        return 0
    n = len(arr)
    forward = [0] * n
    backward = [0] * n
    forward[0] = arr[0]
    for i in range(1, n):
        forward[i] = max(forward[i-1], arr[i])
    backward[-1] = arr[-1]
    for i in range(n-2, -1, -1):
        backward[i] = max(backward[i+1], arr[i])
    return max(forward[i] + backward[i] for i in range(n))

