def max_sum_increasing_subseq(arr, n, i, k):
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for j in range(1, n + 1):
        for l in range(1, min(j + 1, k + 1)):
            max_val = 0
            for m in range(j):
                if arr[m] < arr[j - 1]:
                    max_val = max(max_val, dp[m][l - 1])
            dp[j][l] = max(dp[j - 1][l], arr[j - 1] + max_val)
    return dp[i][k]

