def get_max_sum(n):
    memo = {1: 1}
    def f(n):
        if n in memo:
            return memo[n]
        else:
            max_sum = n
            for i in [2, 3, 4, 5]:
                if n % i == 0:
                    max_sum = max(max_sum, f(n // i) + f(n // i))
            memo[n] = max_sum
            return max_sum
    return f(n)

