def bell_number(n):
    if n == 0:
        return 1
    B = [0] * (n + 1)
    B[0] = 1
    for i in range(1, n + 1):
        B[i] = sum(comb(i - 1, j - 1) * B[j] for j in range(1, i + 1))
    return B[n]

def comb(n, k):
    if k > n - k:
        k = n - k
    result = 1
    for i in range(k + 1, n + 1):
        result *= i
    for i in range(1, n - k + 1):
        result //= i
    return result

