def largest_subset(nums):
    def is_divisible(i, j):
        return (nums[i] + nums[j]) % 2 == 0

    n = len(nums)
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                if is_divisible(i, k) and is_divisible(k + 1, j):
                    dp[i][j] = dp[i][j] or dp[i][k] and dp[k + 1][j]
            if is_divisible(i, j):
                dp[i][j] = True

    max_length = 0
    for i in range(n):
        for j in range(i, n):
            if dp[i][j]:
                max_length = max(max_length, j - i + 1)

    return max_length

